    "unitId": "n2:integrated-comprehension:2019-12:1:line-3",
    "text": "それなら、陶芸教室は？茶碗とか、お皿とか作るの、陶器は焼くのに2・3週間かかるけど、後で国に送ってくれるよ。それから、布を染める教室もお勧め、スカーフを染めるんだけど、日本の伝統的な色を使うから、日本らしいお土産になるし、その日に持ち帰れるよ。",
