    "unitId": "n2:integrated-comprehension:2019-12:1:line-9",
    "text": "だけど、料理は今昼間しかやってないんだ。お寿司とか作れて楽しいし、箸には名前を入れてプレゼントしてくれるから、すごく人気なんだけど、茶道のほうは、夜7時まで、1時間ごとに好きな時間で予約できるよ、お土産に和菓子もらえるけど、食べたら残らないね。四つの教室のどれかするなら、私が予約するよ",
